import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Only exact native KNOCKBACK_RESISTANCE name getter; no dynamic IAttribute receivers. */
public class KnockbackNameScanner {
 public static void main(String[] args)throws Exception{
  JavaCompiler compiler=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> errors=new DiagnosticCollector<>();StandardJavaFileManager fm=compiler.getStandardFileManager(errors,null,null);JavacTask task=(JavacTask)compiler.getTask(null,fm,errors,Arrays.asList("-proc:none","-classpath",new String(Files.readAllBytes(Paths.get(args[1]))).trim(),"-Xmaxerrs","10000"),null,fm.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(args[0]))));List<CompilationUnitTree> units=new ArrayList<>();for(CompilationUnitTree u:task.parse())units.add(u);task.analyze();Trees trees=Trees.instance(task);SourcePositions positions=trees.getSourcePositions();boolean after=args.length>2&&args[2].equals("after");
  for(CompilationUnitTree u:units){String file=Paths.get(u.getSourceFile().toUri()).toString(),rel=file.substring(file.indexOf("src/main/java/"));new TreePathScanner<Void,Void>(){
   public Void visitImport(ImportTree n,Void p){return null;}
   public Void visitMethodInvocation(MethodInvocationTree n,Void p){if(n.getArguments().isEmpty()&&n.getMethodSelect() instanceof MemberSelectTree){MemberSelectTree method=(MemberSelectTree)n.getMethodSelect();if(method.getIdentifier().contentEquals(after?"getName":"getAttributeUnlocalizedName")&&method.getExpression() instanceof MemberSelectTree){MemberSelectTree field=(MemberSelectTree)method.getExpression();TreePath mp=new TreePath(getCurrentPath(),method),fp=new TreePath(mp,field),qp=new TreePath(fp,field.getExpression());Element owner=trees.getElement(qp),f=trees.getElement(fp);if(owner instanceof TypeElement&&((TypeElement)owner).getQualifiedName().contentEquals("net.minecraft.entity.SharedMonsterAttributes")&&field.getIdentifier().contentEquals("KNOCKBACK_RESISTANCE")){if(f==null||f.getKind()!=ElementKind.FIELD||!f.getEnclosingElement().toString().equals("net.minecraft.entity.SharedMonsterAttributes")||!f.asType().toString().equals("net.minecraft.entity.ai.attributes.IAttribute")||!f.getModifiers().containsAll(Arrays.asList(Modifier.PUBLIC,Modifier.STATIC,Modifier.FINAL)))throw new AssertionError("wrong field: "+f);if(after){Element getter=trees.getElement(mp);if(getter==null||!getter.getEnclosingElement().toString().equals("net.minecraft.entity.ai.attributes.IAttribute")||!getter.getSimpleName().contentEquals("getName"))throw new AssertionError("wrong getter");}String old=after?"getName":"getAttributeUnlocalizedName";long end=positions.getEndPosition(u,method);System.out.println(rel+"\t"+(end-old.length())+"\t"+end+"\t"+old+"\tgetName");}}}return super.visitMethodInvocation(n,p);}
  }.scan(u,null);}System.err.println("Isolated-owner attribution only; expected unrelated incomplete-owner errors: "+errors.getDiagnostics().stream().filter(e->e.getKind()==Diagnostic.Kind.ERROR).count());fm.close();
 }
}
